useEffect(() => {
  const { add } = notificationDebugger();
  const TOPIC = `/user/${userName}/cashflow/notification`;
  const notificationPool = new CashflowNotificationPool<NotifiedCashflow>({
    recordKey: "Cashflow_Id",
  });
  window.notificationPool = notificationPool;
  const clearNotification = subscribeCashflowNotification(
    TOPIC,
    id,
    (message) => {
      if (isCashflow(message?.Cashflow))
        notificationPool.add(message as unknown as NotifiedCashflow);
      add(message);
    },
    () => {
      notificationPool.unsubscribeAll();
      notificationPool.subscribe((cashflows) => {
        if (cashflows.length) onCashflowComming(cashflows);
      });
    },
    (_frame, reconnectCallback) => {
      popReconnectNotification(reconnectCallback, id);
    }
  );
  return () => {
    clearNotification();
    notificationPool.destory();
  };
}, []);

private publish() {
  if (this.listeners.length && this.pool.length) {
    this.clearOutDateData();
    this.listeners.forEach((f) => f(this.pool));
    this.pool = [];
  }

start() {
  this.stop();
  this.intervalHandler = window.setInterval(() => {
    this.publish();
  }, this.holdingTime);

export const notificationUpdateOrAddingCashflows = (
  cashflowInstances: CNCashflow[] | NotifiedCashflow[]
) => {
  return async (dispatch: Dispatch, getState: () => RootState) => {
    if (isEmptyArray(cashflowInstances)) return;
    const { cashflowListQueryStatus } = getState();
    await cashflowListQueryStatus; // blotter loading
    const {
      cashflowGridEvent,
      quickFilters,
      searchFilters,
      cashflowList,
      cashflowListPagination,
      viewCashflowDetailsWorkflow,
    } = getState();
    const { api } = cashflowGridEvent as GridReadyEvent;
    const cashflows = filterOutCashflow(cashflowInstances);
    // apply filter
    let allFilters = transformAllVariableDates(
      combineRuleGroups(searchFilters, quickFilters)
    );
    if (allFilters.rules.length === 0)
      allFilters = legacyFilters2Query(getCashflowDefaultFilter());
    const [filteredCashflows, droppedCashflows] = matchQueries<CNCashflow>(
      cashflows,
      allFilters
    );

    const {
      updatedCashflows,
      deletedCashflows,
      newCashflowList,
      originCashflowsBeUpdated,
    } = handleCashflowsData(cashflowList, filteredCashflows, droppedCashflows);
    const addedCashflows: CNCashflow[] = filteredCashflows;

    if (
      isCashflowListNotChanges(
        updatedCashflows,
        addedCashflows,
        deletedCashflows
      )
    )
      return;

  const deletedCashflowsIds = deletedCashflows.map(
    (c) => c.Cashflow?.Cashflow_Id
  );
  // store
  dispatch({
    type: types.SET_CASHFLOW_LIST,
    data: [
      ...addedCashflows,
      ...newCashflowList.filter(
        (c) => !deletedCashflowsIds.includes(c.Cashflow?.Cashflow_Id)
      ),
    ],
  });
  // 1. first loaded -> totally hits
  // 2. totally hits -> all data
  // 3. new data
  // 1&2 can't be indentified
  let paginationNewRowsSize = addedCashflows.length;
  if (isCashflowPaginationChanges(paginationNewRowsSize, deletedCashflows)) {
    dispatch({
      type: types.SET_CASHFLOW_LIST_PAGINATION,
      data: {
        ...cashflowListPagination,
        totalHits:
          cashflowListPagination.totalHits +
          paginationNewRowsSize -
          deletedCashflows.length,
      },
    });
  }

  // level2 updating
  const { isOpenCashflowDetails, data: cashflowDetailsData } =
    viewCashflowDetailsWorkflow;
  if (isOpenCashflowDetails) {
    const targetCashflow = cashflows.find((cf) =>
      isSameCashflow(cf, cashflowDetailsData)
    );
    if (
      targetCashflow &&
      isCashflowUpdated(cashflowDetailsData, targetCashflow)
    ) {
      // alert refresh
      dispatch({
        type: types.SET_DIALOG_REFRESH_ALERT,
        data: {
          showAlert: true,
          onClickRefresh: (actions: string[]) => {
            if (actions.includes("hidemodal")) {
              dispatch({
                type: types.SET_DIALOG_REFRESH_ALERT,
                data: {
                  showAlert: false,
                  onClickRefresh: () => {},
                },
              });
            }
            if (actions.includes("refresh")) {
              dispatch(
                viewCashflowDetailsAction({
                  ...viewCashflowDetailsWorkflow,
                  data: targetCashflow,
                })
              );
            }
          },
        },
      });
    }
  }
};

export function socketClientFactory(url: string, id: string): ISocketClient {
  const uid = getUid(url, id);
  const socketClientExisted = socketClientStore.get(uid);

  if (socketClientExisted) {
    return socketClientExisted;
  } else {
    const client = Stomp.over(new SockJS(url, undefined, { timeout: 1000 }));
    client.heartbeat.outgoing = 3000;
    client.heartbeat.incoming = 25000;

export const subscribeCashflowNotification = (
  topic: string,
  id: string,
  callback: (message: Record<string, object>) => void,
  onConnected: (frame: Frame | undefined) => void,
  onError: (frame: Frame | string, cb: () => void) => void
) => {
  const url = CASHFLOW_NOTIFICATION_SUBSCRIPTIONS;
  return subscribeSocketNotification({
    url,
    id,
    topic: {
      destination: topic,
      callback,
    },
    onConnected,
    onError,
  });

